```js
function assertFiniteNumber(value, name) {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new TypeError(`${name} must be a finite number`);
  }
}

export function calculateTotal(items, taxRate = 0) {
  if (!Array.isArray(items)) {
    throw new TypeError('items must be an array');
  }

  assertFiniteNumber(taxRate, 'taxRate');

  if (taxRate < 0) {
    throw new RangeError('taxRate cannot be negative');
  }

  if (items.length === 0) {
    return 0;
  }

  const subtotal = items.reduce((sum, item, index) => {
    if (item == null || typeof item !== 'object') {
      throw new TypeError(`items[${index}] must be an object`);
    }

    const { price, quantity } = item;

    assertFiniteNumber(price, `items[${index}].price`);
    assertFiniteNumber(quantity, `items[${index}].quantity`);

    if (price < 0) {
      throw new RangeError(`items[${index}].price cannot be negative`);
    }

    if (quantity < 0) {
      throw new RangeError(`items[${index}].quantity cannot be negative`);
    }

    return sum + price * quantity;
  }, 0);

  const total = subtotal * (1 + taxRate);
  return Math.round(total * 100) / 100;
}
```

2) test/pricing/calculateTotal.test.js
```js
import { calculateTotal } from '../../src/pricing/calculateTotal';

describe('calculateTotal', () => {
  it('calculates subtotal with tax', () => {
    const items = [
      { price: 10, quantity: 2 },
      { price: 5, quantity: 1 }
    ];

    expect(calculateTotal(items, 0.1)).toBe(27.5);
  });

  it('returns 0 for empty items', () => {
    expect(calculateTotal([], 0.2)).toBe(0);
  });

  it('returns 0 when item quantity is zero', () => {
    expect(calculateTotal([{ price: 10, quantity: 0 }], 0.2)).toBe(0);
  });

  it('throws when items is not an array', () => {
    expect(() => calculateTotal(null, 0.2)).toThrow('items must be an array');
  });

  it('throws when taxRate is negative', () => {
    expect(() => calculateTotal([], -0.1)).toThrow('taxRate cannot be negative');
  });

  it('throws when price is negative', () => {
    expect(() => calculateTotal([{ price: -1, quantity: 1 }], 0)).toThrow(
      'items[0].price cannot be negative'
    );
  });

  it('throws when quantity is negative', () => {
    expect(() => calculateTotal([{ price: 1, quantity: -1 }], 0)).toThrow(
      'items[0].quantity cannot be negative'
    );
  });

  it('throws when price is missing or non-numeric', () => {
    expect(() => calculateTotal([{ quantity: 1 }], 0)).toThrow(
      'items[0].price must be a finite number'
    );
  });

  it('rounds currency results to two decimals', () => {
    expect(calculateTotal([{ price: 0.1, quantity: 3 }], 0)).toBe(0.3);
  });
});
```

